const weekTitles = roadmapWeeks.map((week) => week.title);
const isRoadmapWeekComplete = (
  week: number,
  completedWeeks: number[],
  completedTopics: string[],
) => {
  if (completedWeeks.includes(week) || completedTopics.includes(`week-${week}:complete`)) return true;
  const topicIds = roadmapWeeks[week - 1]?.topics.map((_, index) => `week-${week}:topic-${index + 1}`) ?? [];
  return topicIds.length > 0 && topicIds.every((topicId) => completedTopics.includes(topicId));
};
const currentRoadmapWeek = (completedWeeks: number[], completedTopics: string[] = []) =>
  Array.from({ length: 40 }, (_, index) => index + 1).find(
    (week) => !isRoadmapWeekComplete(week, completedWeeks, completedTopics),
  ) ?? 40;
