function ClerkCacheInvalidator() { const { addListener } = useClerk(); const qc = useQueryClient(); const prev = useRef<string | null | undefined>(undefined); useEffect(()=>{const unsub=addListener(({user})=>{const id=user?.id??null;if(prev.current!==undefined&&prev.current!==id)qc.clear();prev.current=id;});return unsub;},[addListener,qc]); return null; }
function ProfileBadge() { const { user } = useUser(); const { signOut } = useClerk(); const [open,setOpen]=useState(false); const initials=(user?.fullName||'LS').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase(); return <div className="relative"><button data-testid="button-profile-menu" onClick={()=>setOpen(!open)} className="flex items-center gap-2 rounded-xl border border-slate-700/70 bg-slate-900/40 p-1.5 pr-3 hover:bg-slate-800"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-cyan-300/15 font-mono text-xs font-semibold text-cyan-200">{initials}</span><span className="hidden max-w-[125px] truncate text-xs font-medium text-slate-300 sm:block">{user?.firstName||'Student'}</span><ChevronDown size={13} className="text-slate-500"/></button>{open&&<div className="panel absolute right-0 top-12 z-50 w-48 rounded-xl p-2"><Link href="/profile" onClick={()=>setOpen(false)} className="block rounded-lg px-3 py-2 text-sm text-slate-300 hover:bg-slate-800" data-testid="link-profile-menu">Your profile</Link><button data-testid="button-sign-out" onClick={()=>signOut({redirectUrl:basePath||'/'})} className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-sm text-slate-400 hover:bg-slate-800 hover:text-slate-100"><LogOut size={14}/>Sign out</button></div>}</div>; }
