function Projects({state,patch}:any){
 const completed=(projectId:string,milestoneId:string)=>state.projectMilestones.some((x:any)=>x.projectId===projectId&&x.milestoneId===milestoneId&&x.completed);
 const toggle=(projectId:string,milestoneId:string)=>patch((s:Workspace)=>({...s,projectMilestones:s.projectMilestones.some((x:any)=>x.projectId===projectId&&x.milestoneId===milestoneId)?s.projectMilestones.map((x:any)=>x.projectId===projectId&&x.milestoneId===milestoneId?{...x,completed:!x.completed}:x):[...s.projectMilestones,{projectId,milestoneId,completed:true}]}));
  return <div className="fade-up"><PageHeading eyebrow="LEARN IT. BUILD IT. EXPLAIN IT." title="Projects" subtitle="Two guided security projects turn your learning into interview stories with real structure." aside={<div className="font-mono text-[10px] text-slate-500">2 ASSIGNED PROJECTS</div>}/><div className="grid gap-5 xl:grid-cols-2">{projectSpecs.map((p,index)=>{const done=p.milestones.filter((_,i)=>completed(p.id,String(i))).length;return <Panel key={p.id} className="overflow-hidden"><div className="relative border-b border-slate-700/60 p-5 sm:p-6"><div className="absolute right-5 top-5 flex h-10 w-10 items-center justify-center rounded-xl border border-cyan-300/15 bg-cyan-300/[.07] text-cyan-200"><FolderKanban size={18}/></div><div className="font-mono text-[9px] uppercase tracking-[.17em] text-cyan-300/75">{p.type} · 0{index+1}</div><h2 className="mt-3 max-w-sm font-serif text-xl font-bold leading-7">{p.name}</h2><p className="mt-2 max-w-lg text-xs leading-5 text-slate-400">{p.description}</p><Link href={`/roadmap/week/${p.week}`} data-testid={`link-project-week-${p.week}`} className="mt-3 inline-flex items-center gap-1 text-[10px] font-semibold text-cyan-200">Roadmap week {p.week} <ArrowRight size={12}/></Link><div className="mt-4 flex flex-wrap gap-1.5">{p.skills.map(skill=><span key={skill} className="rounded-md border border-slate-700/70 bg-slate-900/30 px-2 py-1 text-[9px] text-slate-400">{skill}</span>)}</div></div><div className="p-5"><div className="mb-3 flex justify-between text-[10px]"><span className="font-semibold text-slate-300">Milestones</span><span className="font-mono text-slate-500">{done}/{p.milestones.length} complete</span></div><ProgressBar value={done/p.milestones.length*100} testId={`progress-project-${p.id}`}/><div className="mt-4 space-y-2">{p.milestones.map((m,i)=>{const checked=completed(p.id,String(i));return <button key={m} data-testid={`milestone-${p.id}-${i}`} onClick={()=>toggle(p.id,String(i))} className="flex w-full items-center gap-3 rounded-lg px-2.5 py-2 text-left hover:bg-slate-800/50"><span className={cx('flex h-5 w-5 items-center justify-center rounded-md border',checked?'border-emerald-300/50 bg-emerald-300/10 text-emerald-200':'border-slate-600 text-transparent')}><Check size={12}/></span><span className={cx('text-xs',checked?'text-slate-500 line-through':'text-slate-300')}>{m}</span></button>})}</div><div className="mt-5 rounded-xl border border-slate-700/60 bg-slate-900/30 p-4"><div className="flex items-center gap-2 text-xs font-semibold"><Sparkles size={14} className="text-cyan-200"/>Interview story prompts</div><ul className="mt-2 space-y-1.5 text-[10px] leading-4 text-slate-500">{['What risk mattered most, and why?','How did you choose your recommendations?','What would you improve with more time?'].map(q=><li key={q}>— {q}</li>)}</ul><Link href="/interview" className="mt-3 inline-flex items-center gap-1 text-[10px] font-semibold text-cyan-200" data-testid={`project-interview-${p.id}`}>Write your project answers <ArrowRight size={12}/></Link></div></div></Panel>})}</div></div>;
}
