const TEST_DURATION_SECONDS=20*60;
function MockTests({state,patch}:any){
 const categories=['All','Python','DSA','SQL','Aptitude','Core CS','Cybersecurity','Cloud security','Networking','Interview'];const [category,setCategory]=useState('All');const [active,setActive]=useState(false);const [index,setIndex]=useState(0);const [answer,setAnswer]=useState<number|null>(null);const [score,setScore]=useState(0);const [incorrect,setIncorrect]=useState<string[]>([]);const [started,setStarted]=useState(0);const [timeRemaining,setTimeRemaining]=useState(TEST_DURATION_SECONDS);const [showResult,setShowResult]=useState(false);
 const filtered=quizQuestions.filter(q=>category==='All'||q.category===category);const q=filtered[index%Math.max(filtered.length,1)];const history=state.mockTests;const timerLabel=`${String(Math.floor(timeRemaining/60)).padStart(2,'0')}:${String(timeRemaining%60).padStart(2,'0')}`;
 const start=()=>{setIndex(0);setAnswer(null);setScore(0);setIncorrect([]);setStarted(Date.now());setTimeRemaining(TEST_DURATION_SECONDS);setActive(true);setShowResult(false);};
 useEffect(()=>{if(!active)return;const timer=window.setInterval(()=>setTimeRemaining(value=>Math.max(0,value-1)),1000);return()=>window.clearInterval(timer);},[active]);
 useEffect(()=>{if(!active||timeRemaining>0)return;patch((s:Workspace)=>({...s,mockTests:[{id:`mock-${Date.now()}`,category:category==='All'?'Full placement simulation':category,score,total:filtered.length,durationSeconds:TEST_DURATION_SECONDS,completedAt:new Date().toISOString(),incorrectTopics:Array.from(new Set(incorrect))},...s.mockTests]}));setActive(false);setShowResult(true);},[active,timeRemaining]);
 const submit=()=>{if(answer===null)return;const nextScore=score+(answer===q.answer?1:0);const nextIncorrect=answer===q.answer?incorrect:[...incorrect,q.category];setScore(nextScore);setIncorrect(nextIncorrect);if(index+1>=filtered.length){patch((s:Workspace)=>({...s,mockTests:[{id:`mock-${Date.now()}`,category:category==='All'?'Full placement simulation':category,score:nextScore,total:filtered.length,durationSeconds:Math.round((Date.now()-started)/1000),completedAt:new Date().toISOString(),incorrectTopics:Array.from(new Set(nextIncorrect))},...s.mockTests]}));setActive(false);setShowResult(true);}else{setIndex(index+1);setAnswer(null);}};
 return <div className="fade-up"><PageHeading eyebrow="PRACTICE THE PRESSURE, NOT THE PANIC" title="Mock tests" subtitle="Timed quizzes with explanations, saved scores, and weak-topic review. Assessment patterns vary by role and drive; follow the current MITS placement notice." aside={<div className="font-mono text-[10px] text-slate-500">{history.length} COMPLETED</div>}/><div className="mb-5 flex gap-2 overflow-x-auto nav-scroll">{categories.map(c=><button key={c} data-testid={`mock-filter-${c.toLowerCase().replace(/\s/g,'-')}`} onClick={()=>{setActive(false);setShowResult(false);setCategory(c);setIndex(0)}} className={cx('whitespace-nowrap rounded-xl border px-3 py-2 text-[10px] font-semibold',category===c?'border-cyan-300/25 bg-cyan-300/10 text-cyan-100':'border-slate-700/70 text-slate-400 hover:text-slate-200')}>{c}</button>)}</div>
 <div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Panel className="overflow-hidden">{active?<div className="p-5 sm:p-7"><div className="flex items-center justify-between"><div className="font-mono text-[10px] uppercase tracking-[.16em] text-cyan-200">{q.category} · QUESTION {index+1}/{filtered.length}</div><div className="flex items-center gap-3 font-mono text-[10px]"><span data-testid="mock-timer" className={timeRemaining<60?'text-rose-200':'text-cyan-200'}>{timerLabel}</span><span className="text-slate-500">SCORE {score}</span></div></div><div className="mt-6 font-serif text-xl font-bold leading-8 text-slate-100">{q.question}</div><div className="mt-5 space-y-2">{q.options.map((o,i)=><button key={o} data-testid={`mock-answer-${i}`} onClick={()=>setAnswer(i)} className={cx('flex w-full items-center gap-3 rounded-xl border p-3.5 text-left text-xs transition',answer===i?'border-cyan-300/40 bg-cyan-300/[.07] text-cyan-100':'border-slate-700/70 bg-slate-900/30 text-slate-300 hover:border-slate-600')}><span className={cx('flex h-6 w-6 items-center justify-center rounded-lg border font-mono text-[10px]',answer===i?'border-cyan-300/35 bg-cyan-300/10':'border-slate-700 bg-slate-800/50')}>{String.fromCharCode(65+i)}</span>{o}</button>)}</div>{answer!==null&&<div className={cx('mt-4 rounded-xl border p-3.5 text-xs leading-5',answer===q.answer?'border-emerald-300/20 bg-emerald-300/[.06] text-emerald-100':'border-amber-300/20 bg-amber-300/[.05] text-amber-100')}><div className="font-semibold">{answer===q.answer?'That’s right.':'Not quite — here’s the useful part.'}</div><div className="mt-1 opacity-80">{q.explanation}</div></div>}<div className="mt-5 flex justify-between"><Button testId="button-exit-quiz" onClick={()=>{setActive(false);setShowResult(false)}} kind="quiet">Exit test</Button><Button testId="button-submit-answer" onClick={submit} kind="primary" disabled={answer===null}>{index+1===filtered.length?'Finish test':'Next question'} <ArrowRight size={14}/></Button></div></div>:showResult?<div className="p-7 text-center"><div className="mx-auto flex h-12 w-12 items-center justify-center rounded-xl bg-emerald-300/10 text-emerald-200"><Trophy size={21}/></div><div className="mt-4 font-mono text-[10px] uppercase tracking-[.17em] text-cyan-200">Session complete</div><h2 className="mt-2 font-serif text-3xl font-bold">{score} <span className="text-slate-500">/ {filtered.length}</span></h2><p className="mt-2 text-xs text-slate-400">Review the explanations and revisit any topic that felt uncertain.</p>{category==='All'&&<Link href="/interview" data-testid="link-mock-interview-next" className="mt-4 inline-flex items-center gap-1.5 text-xs text-cyan-200">Continue with project and HR interview practice <ArrowRight size={13}/></Link>}<div><Button testId="button-retry-quiz" kind="primary" onClick={start} className="mt-5">Try again <ArrowRight size={14}/></Button></div></div>:<div className="p-6 sm:p-8"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-cyan-300/[.08] text-cyan-200"><Timer size={19}/></div><div className="mt-6 font-mono text-[10px] uppercase tracking-[.16em] text-cyan-300/70">A focused practice set</div><h2 className="mt-2 font-serif text-2xl font-bold">{category==='All'?'Mixed readiness check':`${category} check`}</h2><p className="mt-2 max-w-md text-xs leading-6 text-slate-400">{filtered.length} questions. Timed with a 20-minute limit; review each explanation after the test.</p><div className="mt-6 flex items-center gap-4 text-[10px] text-slate-500"><span className="flex items-center gap-1.5"><ListChecks size={13}/> {filtered.length} questions</span><span className="flex items-center gap-1.5"><Clock3 size={13}/> 20 min max</span></div><Button testId="button-start-quiz" kind="primary" onClick={start} className="mt-6"><Zap size={14}/>Start this test</Button></div>}</Panel>
 <Panel className="overflow-hidden"><div className="flex items-center justify-between border-b border-slate-700/60 px-5 py-4"><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-slate-500">Your history</div><div className="mt-1 text-xs text-slate-300">{history.length} tests recorded</div></div><Timer size={16} className="text-slate-500"/></div>{history.length? <div className="divide-y divide-slate-700/40">{history.slice(0,8).map((t:any)=><div key={t.id} className="flex items-center gap-3 px-5 py-4"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-slate-800 text-cyan-200"><CheckCircle2 size={15}/></div><div className="min-w-0 flex-1"><div className="truncate text-xs font-semibold text-slate-200">{t.category} test</div><div className="mt-1 text-[10px] text-slate-500">{new Date(t.completedAt).toLocaleDateString()} · {Math.round(t.durationSeconds/60)} min</div>{t.incorrectTopics?.length>0&&<div data-testid={`mock-weak-topics-${t.id}`} className="mt-1 text-[9px] text-amber-200/75">Review: {t.incorrectTopics.join(', ')}</div>}</div><span className="font-mono text-xs text-cyan-200">{t.score}/{t.total}</span><button data-testid={`mock-delete-${t.id}`} onClick={()=>patch((s:Workspace)=>({...s,mockTests:s.mockTests.filter((x:any)=>x.id!==t.id)}))} className="rounded p-1 text-slate-600 hover:text-rose-200"><X size={13}/></button></div>)}</div>:<div className="px-6 py-14 text-center"><div className="mx-auto flex h-10 w-10 items-center justify-center rounded-xl bg-slate-800 text-slate-500"><FileText size={18}/></div><h3 className="mt-3 text-sm font-semibold">No test history yet</h3><p className="mt-1 text-xs text-slate-500">Your scores and weak topics will be saved here.</p></div>}</Panel></div></div>;
}
const interviewPrompts=[
 {id:'self-introduction',section:'HR & behavioral',prompt:'Introduce yourself in one minute and explain what brought you to cybersecurity.'},
 {id:'why-cognizant',section:'HR & behavioral',prompt:'Why are you interested in Cognizant and the GenC Next role?'},
 {id:'why-cybersecurity',section:'HR & behavioral',prompt:'Why did you choose cybersecurity, and what part of it interests you most?'},
 {id:'strengths',section:'HR & behavioral',prompt:'What are your strengths? Give a specific example.'},
 {id:'weaknesses',section:'HR & behavioral',prompt:'What is one area you are improving, and what are you doing about it?'},
 {id:'career-goals',section:'HR & behavioral',prompt:'What are your career goals for the next few years?'},
 {id:'python-dsa',section:'Technical foundations',prompt:'Explain a Python or DSA problem you solved, including your approach and complexity.'},
 {id:'sql-dbms',section:'Technical foundations',prompt:'Explain how you would use SQL joins and describe one DBMS concept such as normalization or ACID.'},
 {id:'core-cs-networks',section:'Technical foundations',prompt:'Explain one OS concept and how a web request travels through a network.'},
 {id:'cyber-cloud',section:'Cybersecurity & cloud',prompt:'Describe a web-security risk and one cloud control that helps reduce it.'},
 {id:'password-checker-project',section:'Project stories',prompt:'Explain your Password Strength Checker, its design choices, tests, and limitations.'},
 {id:'cloud-monitoring-project',section:'Project stories',prompt:'Explain your Cloud Security Monitoring System and how it detects or reports security events.'},
];
function Interview({state,patch}:any){
 const [section,setSection]=useState('All');const [search,setSearch]=useState('');const sections=['All',...Array.from(new Set(interviewPrompts.map(p=>p.section)))];
 const answerFor=(id:string)=>state.interviewAnswers.find((x:any)=>x.id===id)?.answer||'';
 const filtered=interviewPrompts.filter(p=>(section==='All'||p.section===section)&&p.prompt.toLowerCase().includes(search.toLowerCase()));
 return <div className="fade-up"><PageHeading eyebrow="PRACTICE SAYING IT CLEARLY" title="Interview prep" subtitle="Draft honest answers in your own words. Keep examples concrete, and revisit them as your experience grows." aside={<div className="rounded-xl border border-slate-700 bg-slate-900/40 px-3 py-2 font-mono text-[10px] text-slate-400">{state.interviewAnswers.filter((x:any)=>x.answer.trim()).length} DRAFTED</div>}/><div className="grid gap-5 xl:grid-cols-[.7fr_1.3fr]"><div className="space-y-4"><Panel className="p-5"><label className="relative block"><Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500"/><input data-testid="input-interview-search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Find a prompt" className="w-full rounded-xl border border-slate-700 bg-slate-900/50 py-2.5 pl-9 pr-3 text-xs outline-none placeholder:text-slate-600 focus:border-cyan-300/50"/></label><div className="mt-4 space-y-1">{sections.map(x=><button key={x} data-testid={`interview-filter-${x.toLowerCase().replace(/[^a-z]+/g,'-')}`} onClick={()=>setSection(x)} className={cx('flex w-full items-center justify-between rounded-lg px-3 py-2.5 text-left text-xs',section===x?'bg-cyan-300/[.09] text-cyan-100':'text-slate-400 hover:bg-slate-800/70 hover:text-slate-200')}><span>{x}</span><span className="font-mono text-[9px] text-slate-500">{x==='All'?interviewPrompts.length:interviewPrompts.filter(p=>p.section===x).length}</span></button>)}</div></Panel><Panel className="p-5"><div className="flex items-center gap-2 text-xs font-semibold"><Sparkles size={15} className="text-cyan-200"/>A useful answer shape</div><div className="mt-3 space-y-2 text-[10px] leading-5 text-slate-400">{[['Context','Set the scene in one sentence.'],['Action','Be specific about what you did and why.'],['Learning','Close with the outcome or what changed.']].map(([x,y])=><div key={x} className="flex gap-2"><span className="font-semibold text-cyan-200">{x}</span><span>{y}</span></div>)}</div></Panel></div><div className="space-y-3">{filtered.length===0?<Panel className="p-10 text-center"><Search size={22} className="mx-auto text-slate-600"/><p className="mt-3 text-xs text-slate-400">No prompt found. Try another search.</p></Panel>:filtered.map(p=><Panel key={p.id} className="p-4 sm:p-5"><div className="mb-3 flex items-center justify-between gap-3"><span className="rounded-md bg-cyan-300/[.08] px-2 py-1 text-[9px] font-medium text-cyan-100">{p.section}</span><span className={cx('flex items-center gap-1 text-[9px]',answerFor(p.id)?'text-emerald-200':'text-slate-600')}>{answerFor(p.id)?<CheckCircle2 size={11}/>:<Pencil size={10}/>} {answerFor(p.id)?'Draft saved':'Your draft'}</span></div><h3 data-testid={`interview-prompt-${p.id}`} className="text-sm font-semibold leading-6 text-slate-200">{p.prompt}</h3><textarea data-testid={`interview-answer-${p.id}`} value={answerFor(p.id)} onChange={e=>patch((s:Workspace)=>({...s,interviewAnswers:s.interviewAnswers.some((x:any)=>x.id===p.id)?s.interviewAnswers.map((x:any)=>x.id===p.id?{...x,answer:e.target.value}:x):[...s.interviewAnswers,{id:p.id,prompt:p.prompt,section:p.section,answer:e.target.value}]}))} placeholder="Start with the part you know. It can be rough; clarity comes with practice." className="mt-3 min-h-[86px] w-full resize-y rounded-xl border border-slate-700/70 bg-slate-900/35 p-3 text-xs leading-5 text-slate-200 outline-none placeholder:text-slate-600 focus:border-cyan-300/40"/></Panel>)}</div></div></div>;
}
function ProgressPage({state,patch,dashboard}:any){
 const complete=roadmapWeeks.filter(plan=>isRoadmapWeekComplete(plan.week,state.completedWeeks,state.completedTopics)).length;
 const progress=dashboard?.overallProgress??Math.round(complete/40*100);
 const codingSolved=state.codingProblems.filter((problem:any)=>problem.status==='Solved').length;
 const sqlSolved=state.sqlEntries.filter((entry:any)=>entry.completed).length;
 const projectIds=projectSpecs.map(project=>project.id);
 const projectMilestones=state.projectMilestones.filter((item:any)=>projectIds.includes(item.projectId)&&item.completed).length;
 const answered=state.interviewAnswers.filter((item:any)=>item.answer.trim()).length;
 const fullSimulations=state.mockTests.filter((test:any)=>test.category==='Full placement simulation').length;
 const manualKey=(id:string)=>`drive-checklist:${id}`;
 const hasManual=(id:string)=>state.completedTopics.includes(manualKey(id));
 const checklist:{id:string;label:string;done:boolean;manual?:boolean;href?:string}[]=[
  {id:'coding',label:'100 quality coding problems solved (150 is the stretch target)',done:codingSolved>=100,href:'/coding'},
  {id:'sql',label:'100+ SQL queries completed',done:sqlSolved>=100,href:'/sql'},
  {id:'projects',label:'Both projects working and documented',done:projectSpecs.every(project=>project.milestones.every((_,index)=>state.projectMilestones.some((item:any)=>item.projectId===project.id&&item.milestoneId===String(index)&&item.completed))),href:'/projects'},
  {id:'github',label:'GitHub updated with useful project history',done:hasManual('github'),manual:true},
  {id:'resume',label:'One-page cybersecurity-focused resume ready (include only skills you can explain)',done:hasManual('resume'),manual:true},
  {id:'aptitude',label:'Timed aptitude practice completed',done:state.mockTests.some((test:any)=>test.category==='Aptitude'),href:'/mock-tests'},
  {id:'introduction',label:'One-minute self-introduction practiced',done:!!state.interviewAnswers.find((item:any)=>item.id==='self-introduction')?.answer.trim(),href:'/interview'},
  {id:'project-answers',label:'Both project explanations practiced',done:['password-checker-project','cloud-monitoring-project'].every(id=>!!state.interviewAnswers.find((item:any)=>item.id===id)?.answer.trim()),href:'/interview'},
  {id:'core-cs',label:'Core-CS technical questions revised',done:hasManual('core-cs'),manual:true},
  {id:'cybersecurity',label:'Cybersecurity questions revised',done:hasManual('cybersecurity'),manual:true},
  {id:'full-simulations',label:`Three full placement simulations completed (${fullSimulations} timed mixed mocks logged)`,done:hasManual('full-simulations'),manual:true,href:'/mock-tests'},
 ];
 const checklistReady=checklist.filter(item=>item.done).length;
 const toggleChecklist=(id:string)=>patch((s:Workspace)=>{const key=manualKey(id);return {...s,completedTopics:s.completedTopics.includes(key)?s.completedTopics.filter(topic=>topic!==key):[...s.completedTopics,key]};});
 const skills=[['Coding problems',codingSolved,100],['SQL queries',sqlSolved,100],['Security',state.completedTopics.filter((topic:string)=>topic.startsWith('cyber-')).length,8],['Cloud',state.completedTopics.filter((topic:string)=>topic.startsWith('cloud-')).length,8],['Project milestones',projectMilestones,8],['Interview answers',answered,interviewPrompts.length]];
 return <div className="fade-up"><PageHeading eyebrow="THE WORK IS ADDING UP" title="Progress" subtitle="Track the preparation goals from your roadmap and mark the final drive checklist as each item is genuinely ready."/><div className="grid gap-5 xl:grid-cols-[.75fr_1.25fr]"><Panel className="relative overflow-hidden p-6 sm:p-7"><div className="absolute -right-12 -top-12 h-48 w-48 rounded-full bg-cyan-400/[.04] blur-2xl"/><div className="relative font-mono text-[10px] uppercase tracking-[.17em] text-slate-500">Overall preparation</div><div className="relative mt-5 flex items-end gap-2"><span className="font-serif text-6xl font-bold tracking-[-.07em] text-slate-100">{progress}</span><span className="mb-2 font-serif text-2xl text-cyan-200">%</span></div><div className="relative mt-4"><ProgressBar value={progress}/></div><div className="relative mt-4 flex justify-between text-[10px] text-slate-500"><span>{complete} of 40 weeks complete</span><span>40 week plan</span></div><div className="relative mt-7 grid grid-cols-2 gap-3 border-t border-slate-700/60 pt-5"><div><div className="font-mono text-xl font-medium">{state.dailyTasks.filter((task:any)=>task.completed).length}</div><div className="mt-1 text-[10px] text-slate-500">sessions checked off</div></div><div><div className="font-mono text-xl font-medium">{state.mockTests.length}</div><div className="mt-1 text-[10px] text-slate-500">timed test sessions</div></div></div></Panel><Panel className="p-5 sm:p-6"><div className="flex items-center justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[.17em] text-slate-500">Skill areas</div><h2 className="mt-1 font-serif text-lg font-bold">Breadth at a glance</h2></div><Activity size={17} className="text-cyan-200"/></div><div className="mt-5 space-y-4">{skills.map(([name,value,total])=>{const pct=Math.min(100,Math.round(Number(value)/Math.max(Number(total),1)*100));return <div key={name} data-testid={`skill-progress-${name}`}><div className="mb-1.5 flex justify-between text-[10px]"><span className="text-slate-300">{name}</span><span className="font-mono text-slate-500">{value} <span className="text-slate-700">/ {total}</span></span></div><ProgressBar value={pct} testId={`progress-skill-${name.toLowerCase().replace(/\s/g,'-')}`}/></div>})}<p className="text-[10px] leading-5 text-slate-500">Coding goal: 100–150 quality problems. SQL goal: 100+ completed queries.</p></div></Panel></div>
 <Panel className="mt-5 p-5 sm:p-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[.17em] text-cyan-300/75">Before the placement drive</div><h2 className="mt-1 font-serif text-xl font-bold">Final readiness checklist</h2><p className="mt-1 text-xs text-slate-500">Some goals are counted from your trackers; the remaining items are self-checked.</p></div><div className="font-mono text-xs text-cyan-200">{checklistReady}/{checklist.length} ready</div></div><div className="mt-4 grid gap-2 sm:grid-cols-2">{checklist.map(item=><div key={item.id} data-testid={`final-checklist-item-${item.id}`} className="flex items-center gap-3 rounded-xl border border-slate-700/50 bg-slate-900/25 px-3 py-3">{item.manual?<button aria-pressed={item.done} onClick={()=>toggleChecklist(item.id)} className={cx('flex h-5 w-5 shrink-0 items-center justify-center rounded-md border',item.done?'border-cyan-300 bg-cyan-300 text-[#09202a]':'border-slate-600 text-transparent')}><Check size={12}/></button>:<span className={cx('flex h-5 w-5 shrink-0 items-center justify-center rounded-md border',item.done?'border-emerald-300/50 bg-emerald-300/10 text-emerald-200':'border-slate-600 text-transparent')}><Check size={12}/></span>}<span className={cx('min-w-0 flex-1 text-[11px] leading-5',item.done?'text-slate-400':'text-slate-300')}>{item.label}</span>{item.href&&<Link href={item.href} aria-label={`Open ${item.label}`} className="shrink-0 text-slate-500 hover:text-cyan-200"><ArrowUpRight size={14}/></Link>}</div>)}</div></Panel>
 <div className="mt-5 grid gap-4 lg:grid-cols-2">{phases.map((phase,index)=>{const count=roadmapWeeks.filter(plan=>plan.week>=phase.range[0]&&plan.week<=phase.range[1]&&isRoadmapWeekComplete(plan.week,state.completedWeeks,state.completedTopics)).length;const total=phase.range[1]-phase.range[0]+1;return <Panel key={phase.name} className="p-5"><div className="flex items-start justify-between"><div className="flex items-start gap-3"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-slate-800 font-mono text-[10px] text-cyan-200">{String(index+1).padStart(2,'0')}</div><div><h3 className="text-xs font-semibold text-slate-200">{phase.name}</h3><p className="mt-1 text-[10px] text-slate-500">Weeks {phase.range[0]}–{phase.range[1]}</p></div></div><span className="font-mono text-[10px] text-slate-500">{count}/{total}</span></div><div className="mt-4"><ProgressBar value={count/total*100} testId={`progress-phase-view-${index+1}`}/></div></Panel>})}</div></div>;
}
function Certificates({state,patch}:any){
 const [name,setName]=useState('');const [issuer,setIssuer]=useState('');const [url,setUrl]=useState('');
 const presets=[['AWS Certified Cloud Practitioner','Amazon Web Services'],['Microsoft Certified: Azure Fundamentals','Microsoft'],['CompTIA Security+','CompTIA'],['Google Cybersecurity Certificate','Google']];
 const add=()=>{if(!name.trim())return;patch((s:Workspace)=>({...s,certificates:[{id:`cert-${Date.now()}`,name:name.trim(),issuer:issuer.trim()||'Independent',completed:false,completedAt:null,url},...s.certificates]}));setName('');setIssuer('');setUrl('');};
 const createPreset=(n:string,i:string)=>patch((s:Workspace)=>s.certificates.some((x:any)=>x.name===n)?s:{...s,certificates:[...s.certificates,{id:`cert-${Date.now()}`,name:n,issuer:i,completed:false,completedAt:null,url:''}]});
 return <div className="fade-up"><PageHeading eyebrow="OPTIONAL PROOF OF PRACTICE" title="Certificates" subtitle="Keep planned credentials visible. Choose certifications that support your learning goals and placement story."/><div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><div className="space-y-5"><Panel className="p-5"><div className="flex items-center gap-2 text-xs font-semibold"><Plus size={15} className="text-cyan-200"/>Add a credential</div><div className="mt-4 space-y-3"><input data-testid="input-certificate-name" value={name} onChange={e=>setName(e.target.value)} placeholder="Certificate name" className="w-full rounded-xl border border-slate-700 bg-slate-900/50 px-3 py-2.5 text-sm outline-none placeholder:text-slate-600 focus:border-cyan-300/50"/><input data-testid="input-certificate-issuer" value={issuer} onChange={e=>setIssuer(e.target.value)} placeholder="Issuer or provider" className="w-full rounded-xl border border-slate-700 bg-slate-900/50 px-3 py-2.5 text-sm outline-none placeholder:text-slate-600 focus:border-cyan-300/50"/><input data-testid="input-certificate-url" value={url} onChange={e=>setUrl(e.target.value)} placeholder="Credential link (optional)" className="w-full rounded-xl border border-slate-700 bg-slate-900/50 px-3 py-2.5 text-sm outline-none placeholder:text-slate-600 focus:border-cyan-300/50"/><Button testId="button-add-certificate" kind="primary" onClick={add}><Plus size={14}/>Add certificate</Button></div></Panel><Panel className="p-5"><div className="font-mono text-[10px] uppercase tracking-[.16em] text-slate-500">Consider for your plan</div><div className="mt-3 space-y-2">{presets.map(([n,i])=><button key={n} data-testid={`button-add-preset-${n.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`} onClick={()=>createPreset(n,i)} className="flex w-full items-center gap-2 rounded-lg border border-slate-700/40 px-3 py-2.5 text-left hover:bg-slate-800/50"><Award size={14} className="text-cyan-200"/><span className="min-w-0 flex-1 text-[10px] text-slate-300">{n}</span><Plus size={13} className="text-slate-500"/></button>)}</div></Panel></div><Panel className="overflow-hidden"><div className="flex items-center justify-between border-b border-slate-700/60 px-5 py-4"><div><div className="font-mono text-[10px] uppercase tracking-[.16em] text-slate-500">Credential shelf</div><div className="mt-1 text-xs text-slate-300">{state.certificates.filter((c:any)=>c.completed).length} completed · {state.certificates.filter((c:any)=>!c.completed).length} planned</div></div><Award size={17} className="text-cyan-200"/></div>{state.certificates.length===0?<div className="px-6 py-16 text-center"><div className="mx-auto flex h-11 w-11 items-center justify-center rounded-xl bg-slate-800 text-slate-500"><Award size={19}/></div><h3 className="mt-3 font-serif font-bold">Your credential shelf is open</h3><p className="mt-1 text-xs text-slate-500">Add a planned or completed certification when it supports your path.</p></div>:<div className="divide-y divide-slate-700/40">{state.certificates.map((c:any)=><div key={c.id} className="flex flex-wrap items-center gap-3 px-5 py-4"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-slate-800 text-cyan-200"><Award size={16}/></div><div className="min-w-[120px] flex-1"><div className="text-xs font-semibold text-slate-200">{c.name}</div><div className="mt-1 text-[10px] text-slate-500">{c.issuer}{c.completedAt?` · ${c.completedAt}`:''}</div></div><button data-testid={`certificate-status-${c.id}`} onClick={()=>patch((s:Workspace)=>({...s,certificates:s.certificates.map((x:any)=>x.id===c.id?{...x,completed:!x.completed,completedAt:!x.completed?new Date().toISOString().slice(0,10):null}:x)}))} className={cx('rounded-lg px-2.5 py-1.5 text-[10px] font-semibold',c.completed?'bg-emerald-300/10 text-emerald-200':'bg-slate-800 text-slate-400')}>{c.completed?'Completed':'Planned'}</button>{c.url&&<a href={c.url} target="_blank" rel="noreferrer" className="text-slate-500 hover:text-cyan-200" data-testid={`certificate-link-${c.id}`}><ExternalLink size={14}/></a>}<button data-testid={`certificate-delete-${c.id}`} onClick={()=>patch((s:Workspace)=>({...s,certificates:s.certificates.filter((x:any)=>x.id!==c.id)}))} className="rounded-lg p-1.5 text-slate-600 hover:text-rose-200"><X size={13}/></button></div>)}</div>}</Panel></div></div>;
}
function ProfilePage({state,patch}:any){
 const fields:[keyof Workspace['profile'],string,string][]=[['studentName','Your name','Lakshmi Sai Reddy'],['course','Course of study','B.Tech CSE (Cybersecurity)'],['institute','Institute','Your college or university'],['target','Placement target','Cognizant GenC Next']];
 return <div className="fade-up"><PageHeading eyebrow="YOUR NORTH STAR" title="Profile" subtitle="Keep your preparation context current. This personal profile stays with your workspace."/><div className="grid gap-5 xl:grid-cols-[.72fr_1.28fr]"><Panel className="p-6"><div className="flex h-14 w-14 items-center justify-center rounded-2xl border border-cyan-300/20 bg-cyan-300/[.08] font-serif text-lg font-bold text-cyan-100">LS</div><div className="mt-5 font-serif text-xl font-bold">{state.profile.studentName}</div><div className="mt-1 text-xs text-slate-400">{state.profile.course}</div><div className="mt-5 flex items-center gap-2 border-t border-slate-700/60 pt-4 text-xs text-slate-400"><Target size={14} className="text-cyan-200"/> {state.profile.target}</div><div className="mt-3 flex items-center gap-2 text-[10px] text-slate-500"><CalendarDays size={13}/> {state.profile.preparationWeeks} weeks of preparation</div></Panel><Panel className="p-5 sm:p-6"><div className="font-mono text-[10px] uppercase tracking-[.16em] text-slate-500">Student details</div><div className="mt-5 space-y-4">{fields.map(([key,label,placeholder])=><label key={key} className="block"><span className="mb-1.5 block text-[11px] font-medium text-slate-400">{label}</span><input data-testid={`input-profile-${key}`} value={state.profile[key] as string} onChange={e=>patch((s:Workspace)=>({...s,profile:{...s.profile,[key]:e.target.value}}))} placeholder={placeholder} className="w-full rounded-xl border border-slate-700/70 bg-slate-900/40 px-3.5 py-3 text-sm text-slate-200 outline-none placeholder:text-slate-600 focus:border-cyan-300/50"/></label>)}<label className="block"><span className="mb-1.5 block text-[11px] font-medium text-slate-400">Preparation horizon · weeks</span><div className="flex items-center gap-3"><input data-testid="input-profile-weeks" type="range" min="1" max="40" value={state.profile.preparationWeeks} onChange={e=>patch((s:Workspace)=>({...s,profile:{...s.profile,preparationWeeks:Number(e.target.value)}}))} className="w-full accent-cyan-300"/><span className="w-12 rounded-lg border border-slate-700 bg-slate-900/50 px-2 py-1.5 text-center font-mono text-xs text-cyan-200">{state.profile.preparationWeeks}</span></div></label></div><div className="mt-5 flex items-center gap-2 border-t border-slate-700/60 pt-4 text-[10px] text-slate-500"><CheckCircle2 size={13} className="text-emerald-200"/> Changes save automatically to your workspace.</div></Panel></div></div>;
}
function SettingsPage({state,patch}:any){
 const {signOut}=useClerk();const [confirm,setConfirm]=useState(false);
 return <div className="fade-up"><PageHeading eyebrow="YOUR WORKSPACE, YOUR PACE" title="Settings" subtitle="Adjust the preparation context and manage your account session."/><div className="max-w-3xl space-y-5"><Panel className="p-5 sm:p-6"><div className="flex items-start gap-4"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-cyan-300/[.08] text-cyan-200"><CalendarDays size={18}/></div><div className="flex-1"><h2 className="text-sm font-semibold">Preparation horizon</h2><p className="mt-1 text-xs leading-5 text-slate-500">Your roadmap contains 40 weeks. Set your personal planning window; your roadmap remains available in full.</p><div className="mt-4 flex items-center gap-4"><input data-testid="input-settings-horizon" type="range" min="1" max="40" value={state.profile.preparationWeeks} onChange={e=>patch((s:Workspace)=>({...s,profile:{...s.profile,preparationWeeks:Number(e.target.value)}}))} className="flex-1 accent-cyan-300"/><span data-testid="text-settings-horizon" className="min-w-16 rounded-lg border border-slate-700 bg-slate-900/50 px-3 py-2 text-center font-mono text-xs text-cyan-200">{state.profile.preparationWeeks} weeks</span></div></div></div></Panel><Panel className="p-5 sm:p-6"><div className="flex items-start gap-4"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-slate-800 text-slate-300"><LockKeyhole size={18}/></div><div className="flex-1"><h2 className="text-sm font-semibold">Account session</h2><p className="mt-1 text-xs leading-5 text-slate-500">Your sign-in is managed securely by Clerk. Signing out returns you to the public GENC CRACKER homepage.</p><Button testId="button-settings-signout" onClick={()=>setConfirm(true)} className="mt-4"><LogOut size={14}/>Sign out</Button></div></div></Panel><Panel className="p-5 sm:p-6"><div className="flex items-start gap-4"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-slate-800 text-slate-300"><Settings size={18}/></div><div><h2 className="text-sm font-semibold">Privacy and your preparation data</h2><p className="mt-1 max-w-xl text-xs leading-5 text-slate-500">Your roadmap progress, notes and practice records are stored in your signed-in workspace. They are not shared on a public profile.</p><Link href="/profile" data-testid="link-settings-profile" className="mt-3 inline-flex items-center gap-1 text-xs text-cyan-200">Review profile details <ArrowRight size={13}/></Link></div></div></Panel></div>{confirm&&<div role="dialog" aria-modal="true" className="fixed inset-0 z-50 flex items-center justify-center bg-black/65 p-4"><Panel className="w-full max-w-sm p-6"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-rose-300/10 text-rose-200"><LogOut size={17}/></div><h2 className="mt-4 font-serif text-xl font-bold">Sign out of GENC CRACKER?</h2><p className="mt-2 text-xs leading-5 text-slate-400">Your progress is saved. You can sign back in whenever you’re ready.</p><div className="mt-5 flex justify-end gap-2"><Button testId="button-cancel-signout" onClick={()=>setConfirm(false)}>Stay here</Button><Button testId="button-confirm-signout" kind="primary" onClick={()=>signOut({redirectUrl:basePath||'/'})}>Sign out</Button></div></Panel></div>}</div>;
}
function ProtectedWorkspace(){return <Protected><WorkspaceApp/></Protected>;}
function ClerkRoutes(){
 const [,setLocation]=useLocation();
 return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={clerkAppearance} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} localization={{signIn:{start:{title:'Welcome back',subtitle:'Sign in to pick up where you left off.'}},signUp:{start:{title:'Start your preparation',subtitle:'Build a clear plan for the next 40 weeks.'}}}} routerPush={to=>setLocation(stripBase(to))} routerReplace={to=>setLocation(stripBase(to),{replace:true})}>
  <ClerkCacheInvalidator/>
  <Switch>
   <Route path="/" component={HomeRedirect}/>
   <Route path="/sign-in/*?" component={SignInPage}/>
   <Route path="/sign-up/*?" component={SignUpPage}/>
   <Route path="/dashboard" component={ProtectedWorkspace}/>
   <Route path="/roadmap" component={ProtectedWorkspace}/>
   <Route path="/roadmap/week/:weekNumber" component={ProtectedWorkspace}/>
   <Route path="/timetable" component={ProtectedWorkspace}/>
   <Route path="/resources" component={ProtectedWorkspace}/>
   <Route path="/coding" component={ProtectedWorkspace}/>
   <Route path="/sql" component={ProtectedWorkspace}/>
   <Route path="/aptitude" component={ProtectedWorkspace}/>
   <Route path="/cybersecurity" component={ProtectedWorkspace}/>
   <Route path="/cloud-security" component={ProtectedWorkspace}/>
   <Route path="/projects" component={ProtectedWorkspace}/>
   <Route path="/mock-tests" component={ProtectedWorkspace}/>
   <Route path="/interview" component={ProtectedWorkspace}/>
   <Route path="/progress" component={ProtectedWorkspace}/>
   <Route path="/certificates" component={ProtectedWorkspace}/>
   <Route path="/profile" component={ProtectedWorkspace}/>
   <Route path="/settings" component={ProtectedWorkspace}/>
   <Route component={NotFound}/>
  </Switch>
 </ClerkProvider>;
}
function App(){
 return <QueryClientProvider client={queryClient}><WouterRouter base={basePath}><ClerkRoutes/></WouterRouter></QueryClientProvider>;
}
export default App;